const MEM_KEY = "mem";
const MEM_MAX_BYTES = 200 * 1024;

async function memory(body, env) {
  const kv = env.MEMORY;
  if (!kv || typeof kv.get !== "function") return json({ kv: false });
  if (body.op === "get") {
    const raw = await kv.get(MEM_KEY);
    let mem = null;
    if (raw) { try { mem = JSON.parse(raw); } catch (e) { mem = null; } }
    return json({ kv: true, mem });
  }
  if (body.op === "put") {
    const m = body.mem;
    if (!m || typeof m !== "object" || Array.isArray(m) || !m.memo || typeof m.memo !== "object")
      return json({ error: "記憶のデータの形が正しくありません" }, 400);
    const s = JSON.stringify(m);
    if (new TextEncoder().encode(s).length > MEM_MAX_BYTES) return json({ error: "記憶のデータが大きすぎます（200KBまで）" }, 413);
    await kv.put(MEM_KEY, s);
    return json({ kv: true, ok: true, updatedAt: Number(m.updatedAt) || 0 });
  }
  return json({ error: "op は get か put にしてください" }, 400);
}

