// GET /app/<path> … R2 の app/<path>。html/js/css は no-cache（?v= で版を分ける）、画像は1週間
async function serveAppFile(req, env, url) {
  let p = "";
  try { p = decodeURIComponent(url.pathname.slice(5)); } catch (e) { return new Response("Not found", { status: 404 }); }
  if (p === "" || p === "index.html") return serveHtml(req, env);
  if (p === "manifest.json") {   // v35：アプリの版の確認（pwa.js の自動読み込み直し）。R2 に無い時は埋め込みの版
    let man = null; try { man = env.ARCHIVE ? await appReadManifest(env.ARCHIVE) : null; } catch (e) { man = null; }
    return new Response(JSON.stringify(man || { version: appVerOf(HTML) || WORKER_VERSION, files: [] }), { headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });
  }
  if (p === "schedule-data.js") return new Response("Not found", { status: 404, headers: { "cache-control": "no-store" } });   // v63：v62 で置いた時間割（個人の予定）は配らない。時間割は /api/schedule（パスワード必須）へ
  if (appPathBad(p) || !env.ARCHIVE) return new Response("Not found", { status: 404, headers: { "cache-control": "no-store" } });
  let o = null;
  try { o = await env.ARCHIVE.get(APP_PREFIX + p); } catch (e) { o = null; }
  if (!o) return new Response("Not found", { status: 404, headers: { "cache-control": "no-store" } });
  const ext = appExt(p);
  const h = { "content-type": APP_TYPES[ext], "cache-control": "no-cache", "x-content-type-options": "nosniff" };
  if (o.httpEtag) h.etag = o.httpEtag;
  if (o.httpEtag && req.headers.get("if-none-match") === o.httpEtag) return new Response(null, { status: 304, headers: h });
  return new Response(req.method === "HEAD" ? null : await o.arrayBuffer(), { headers: h });
}


// ---- PWA（インストール対応） ----
const ICONS={"/icon-192.png":"","/icon-512.png":"","/icon-maskable-512.png":"","/apple-touch-icon.png":""};
const MANIFEST={name:"AIコーチ",short_name:"AIコーチ",description:"記録をもとに伴走するAIコーチ",id:"/",start_url:"/?source=pwa",scope:"/",display:"standalone",display_override:["standalone","minimal-ui"],orientation:"portrait",background_color:"#030711",theme_color:"#030711",lang:"ja",
  icons:[{src:"/icon-192.png",sizes:"192x192",type:"image/png",purpose:"any"},{src:"/icon-512.png",sizes:"512x512",type:"image/png",purpose:"any"},{src:"/icon-maskable-512.png",sizes:"512x512",type:"image/png",purpose:"maskable"}]};
const SW_JS=`const C="aicoach-shell-v4";
self.addEventListener("install",e=>{self.skipWaiting();});
self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==C).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
const put=(k,res)=>{if(res&&res.ok){const cp=res.clone();caches.open(C).then(c=>c.put(k,cp));}return res;};
self.addEventListener("fetch",e=>{const r=e.request,u=new URL(r.url);if(r.method!=="GET"||u.origin!==location.origin||u.pathname.startsWith("/api/"))return;
 const key=(r.mode==="navigate"||u.pathname==="/")?"/":r;
 e.respondWith(fetch(r,{cache:"no-cache"}).then(res=>put(key,res)).catch(()=>caches.match(key)));});`;
function servePwa(url,env){
  const p=url.pathname;
  if(p==="/manifest.webmanifest")return (async()=>{let v=WORKER_VERSION;try{if(env&&env.ARCHIVE){const o=await env.ARCHIVE.get("app/manifest.json");if(o){const m=JSON.parse(await o.text());if(m&&m.version)v=String(m.version);}}}catch(e){}
    const mf=Object.assign({},MANIFEST,{icons:MANIFEST.icons.map(i=>Object.assign({},i,{src:i.src+"?v="+encodeURIComponent(v)}))});
    return new Response(JSON.stringify(mf),{headers:{"content-type":"application/manifest+json; charset=utf-8","cache-control":"no-cache"}});})();
  if(p==="/sw.js")return new Response(SW_JS,{headers:{"content-type":"application/javascript; charset=utf-8","cache-control":"no-cache","service-worker-allowed":"/"}});
  if(ICONS[p]&&env&&env.ARCHIVE){return (async()=>{try{const o=await env.ARCHIVE.get("app/icons"+p);if(o)return new Response(o.body,{headers:{"content-type":"image/png","cache-control":"no-cache"}});}catch(e){}const bin=Uint8Array.from(atob(ICONS[p]),c=>c.charCodeAt(0));return new Response(bin,{headers:{"content-type":"image/png","cache-control":"no-cache"}});})();}
  if(ICONS[p]){const bin=Uint8Array.from(atob(ICONS[p]),c=>c.charCodeAt(0));return new Response(bin,{headers:{"content-type":"image/png","cache-control":"no-cache"}});}
  return null;
}

const CORS = { "access-control-allow-origin": "*", "access-control-allow-methods": "GET, POST, OPTIONS", "access-control-allow-headers": "content-type", "access-control-max-age": "86400" };
// ===== v44: 日ごとの集計をCSVで出す（ダウンロード用）。元は stats/daily/（v40） =====
const EXPORT_COLS = ["date", "weekday", "weekday_num", "focus_min", "timer_min", "self_min", "recorded", "result", "sat", "tasks_worked", "tasks_done", "top_task", "did", "note", "sources"];
const expText = s => { s = String(s == null ? "" : s).replace(/\r/g, "").replace(/\n+/g, " ／ ").trim(); return /^[=+\-@\t]/.test(s) || /^[\d.,:\/\s-]+$/.test(s) ? " " + s : s; };   // 表計算が式・数値・日付として読む文には空白を足して文字のままにする
